inline const School* Enrollment::school() const {
    if (school_) {
        return school_.get();
    }
    if (!is_loaded("school")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<School>(ENTITY_NAME, id(), "school");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<School>(schoolId());
}

inline eval::EvalResult<EntityBorrow<School>> Enrollment::evalSchool() const {
    return GeneratedRelationAccess::object(memory_resource(), "school", school(), false);
}

inline void Enrollment::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (school_) {
        school_->attachRuntimeStateRecursive(target);
    }
}

inline Enrollment::Enrollment(std::allocator_arg_t, Allocator a)
    : Base(std::allocator_arg, a),
      id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      school_id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      note_(generated_detail::default_value<String>(a.resource())),
      version_(generated_detail::default_value<std::int64_t>(a.resource())),
      school_(nullptr, detail::ScopedDelete<School>{a.resource()}) {}

inline Enrollment::Enrollment(std::allocator_arg_t, Allocator a, const Enrollment& other)
    : Base(std::allocator_arg, a, other), id_(detail::clone_in(a.resource(), other.id_)),
      school_id_(detail::clone_in(a.resource(), other.school_id_)),
      note_(detail::clone_in(a.resource(), other.note_)),
      version_(detail::clone_in(a.resource(), other.version_)),
      school_(generated_detail::copy_box(a.resource(), other.school_)) {}

inline Enrollment::Enrollment(Enrollment&&) noexcept = default;
inline Enrollment::~Enrollment() = default;

inline EntityDescriptor Enrollment::entity_descriptor(Memory r) {
    EntityDescriptor d(std::allocator_arg, Allocator(r), ENTITY_NAME);
    d.table("enrollment_data");
    d.service("sqlite");
    {
        auto& property = d.property("id", DataType::U64, "id").id().not_null();
        (void)property;
    }
    {
        auto& property = d.property("note", DataType::Text, "note").not_null();
        property.with_max_length(100);
        (void)property;
    }
    {
        auto& property = d.property("version", DataType::I64, "version").version().not_null();
        (void)property;
    }
    {
        auto& property = d.property("school_id", DataType::U64, "school").not_null();
        (void)property;
    }
    {
        auto& relation = d.relation("school", "School");
        relation.local_key = "school_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    d.mask_fields({});
    return d;
}

inline Result<Enrollment, EntityError> Enrollment::from_compact_row(Memory r, CompactRow row) {
    using Outcome = Result<Enrollment, EntityError>;
    Enrollment result(std::allocator_arg, Allocator(r));
    auto captured =
        detail::EntityRuntimeAccess::capture_dynamic_values(result.dynamic, row, field_layout(r));
    if (!captured) {
        return Outcome::err(r, std::move(captured).error());
    }
    auto id_lookup = GeneratedRelationAccess::lookupField(r, row, ENTITY_NAME, "id", "id", false);
    if (!id_lookup) {
        return Outcome::err(r, std::move(id_lookup).error());
    }
    auto school_id_lookup =
        GeneratedRelationAccess::lookupField(r, row, ENTITY_NAME, "school_id", "school", true);
    if (!school_id_lookup) {
        return Outcome::err(r, std::move(school_id_lookup).error());
    }
    auto note_lookup =
        GeneratedRelationAccess::lookupField(r, row, ENTITY_NAME, "note", "note", false);
    if (!note_lookup) {
        return Outcome::err(r, std::move(note_lookup).error());
    }
    auto version_lookup =
        GeneratedRelationAccess::lookupField(r, row, ENTITY_NAME, "version", "version", false);
    if (!version_lookup) {
        return Outcome::err(r, std::move(version_lookup).error());
    }
    auto id_value =
        generated_detail::decode<std::uint64_t>(r, id_lookup.value().value, ENTITY_NAME, "id");
    if (!id_value) {
        return Outcome::err(r, std::move(id_value).error());
    }
    result.id_ = std::move(id_value).value();
    auto school_id_value = generated_detail::decode<std::uint64_t>(
        r, school_id_lookup.value().value, ENTITY_NAME, "school_id");
    if (!school_id_value) {
        return Outcome::err(r, std::move(school_id_value).error());
    }
    result.school_id_ = std::move(school_id_value).value();
    auto note_value =
        generated_detail::decode<String>(r, note_lookup.value().value, ENTITY_NAME, "note");
    if (!note_value) {
        return Outcome::err(r, std::move(note_value).error());
    }
    result.note_ = std::move(note_value).value();
    auto version_value = generated_detail::decode<std::int64_t>(
        r, version_lookup.value().value, ENTITY_NAME, "version");
    if (!version_value) {
        return Outcome::err(r, std::move(version_value).error());
    }
    result.version_ = std::move(version_value).value();
    auto school_decoded = GeneratedRelationAccess::decodeObject<School>(r, row.get("school"));
    if (!school_decoded) {
        return Outcome::err(r, std::move(school_decoded).error());
    }
    if (school_decoded.value()) {
        result.school_ = detail::make_box<School>(r, std::move(*school_decoded.value()));
    }
    result.load_state = row.indexed_load_state(
        detail::ContextArena::from_memory(r).loaded_snapshots(), field_layout(r));
    if (school_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!school_id_lookup.value().object_alias && !row.is_loaded_relation("school")) {
            result.load_state.mark_unloaded("school", &pool).value();
        }
        result.load_state.mark_loaded("school_id", &pool).value();
    }
    result.root.set_original_compact_row(ENTITY_NAME, row);
    return Outcome::ok(r, std::move(result));
}

